package com.nexamart.backend.domain;
import jakarta.persistence.*;import java.math.BigDecimal;import java.time.Instant;
@Entity @Table(name="earnings",indexes=@Index(name="idx_earnings_partner_date",columnList="partner_id,earned_at")) public class Earning{@Id@GeneratedValue(strategy=GenerationType.IDENTITY)private Long id;@ManyToOne(optional=false)@JoinColumn(name="partner_id")private UserAccount partner;@ManyToOne(optional=false)private Order order;private Instant earnedAt=Instant.now();@Column(nullable=false,precision=19,scale=2)private BigDecimal amount;private String currencyCode="INR";@Enumerated(EnumType.STRING)private EarningStatus status=EarningStatus.AVAILABLE;private String description;public Long getId(){return id;}public UserAccount getPartner(){return partner;}public void setPartner(UserAccount v){partner=v;}public Order getOrder(){return order;}public void setOrder(Order v){order=v;}public Instant getEarnedAt(){return earnedAt;}public BigDecimal getAmount(){return amount;}public void setAmount(BigDecimal v){amount=v;}public String getCurrencyCode(){return currencyCode;}public EarningStatus getStatus(){return status;}public String getDescription(){return description;}public void setDescription(String v){description=v;}}
